// Independently adapted from the existing Triomi WEBTOON public HTML rule.
// Pinned protocol reference: keiyoushi/extensions-source@dbf6c05d6a9520c60533f1626616263522bbe71a
// src/zh/dongmanmanhua (Apache-2.0, reference only; upstream code not copied).
// Distinct official Chinese service: no webtoons.com hostname rewriting.
var ORIGIN = 'https://www.dongmanmanhua.cn';
function param(url, name) {
  var match = String(url).match(new RegExp('[?&]' + name + '=([^&#]*)'));
  return match ? decodeURIComponent(match[1]) : '';
}
function official(url) {
  if (!/^https:\/\/www\.dongmanmanhua\.cn\//.test(String(url))) throw new Error('咚漫：仅支持 dongmanmanhua.cn 官方公开网页');
  return String(url);
}
function titleId(url) {
  official(url);
  var value = param(url, 'title_no') || (/\/episodeList\?/.test(url) ? param(url, 'titleNo') : '');
  if (!/^[1-9]\d*$/.test(value)) throw new Error('咚漫：作品地址缺少编号');
  return value;
}
function listUrl(url) {
  var value = titleId(url);
  if (!/\/list\?/.test(url)) throw new Error('咚漫：官方未返回漫画目录地址');
  return url.split('?')[0] + '?title_no=' + value;
}
async function html(url, referer) {
  official(url);
  var result = await triomi.fetch(url, {headers: {Referer: referer || ORIGIN + '/'}});
  if (result.status !== 200) throw new Error('咚漫：HTTP ' + result.status);
  var finalUrl = result.url || url;
  official(finalUrl);
  if (/\/(?:login|ageVerification|age-gate|account)(?:[/?]|$)/i.test(finalUrl)) throw new Error('咚漫：内容需要登录或年龄验证，请使用官方服务');
  if (/服务器停止响应|伺服器停止回應|Access Denied|Just a moment\.\.\./i.test(result.body)) throw new Error('咚漫：官方服务器暂时不可用或限制访问');
  return {body: result.body, url: finalUrl};
}
async function cards(body, url, searching) {
  var rows = await triomi.select(body, searching ? '#content > div.card_wrap.search ul:not(#filterLayer) li a' : 'div#dailyList .daily_section li a, div.daily_lst.comp li a', {
    url: {selector: '.', attr: 'href', absolute: true}, title: {selector: 'p.subj'},
    coverUrl: {selector: 'img', attr: 'src', absolute: true}, author: {selector: '.author'}
  }, url);
  var seen = {}, result = [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i], value = titleId(row.url);
    if (!row.title || !/(?:\/list\?|\/episodeList\?)/.test(row.url)) throw new Error('咚漫：作品列表格式已变更');
    if (!seen[value]) {
      seen[value] = true;
      result.push({remoteId: value, title: row.title, url: /\/list\?/.test(row.url) ? listUrl(row.url) : ORIGIN + '/episodeList?titleNo=' + value, coverUrl: row.coverUrl, author: row.author});
    }
  }
  if (!result.length && !(searching && await triomi.value(body, '#content .card_wrap.search .card_nodata', 'text', url))) throw new Error('咚漫：未找到公开作品列表，可能需要验证或网站已改版');
  return result;
}
async function discover(url, page) {
  if ((page || 1) > 1) return [];
  var response = await html(ORIGIN + '/dailySchedule');
  return cards(response.body, response.url, false);
}
async function search(keyword, page) {
  var url = ORIGIN + '/search?keyword=' + encodeURIComponent(keyword) + ((page || 1) > 1 ? '&page=' + page : '');
  var response = await html(url);
  return cards(response.body, response.url, true);
}
async function detail(url, snapshot) {
  var requestedId = titleId(url), response = await html(url), canonical = listUrl(response.url);
  if (titleId(canonical) !== requestedId) throw new Error('咚漫：官方重新导向了其他作品');
  var body = response.body;
  var rows = await triomi.select(body, 'html', {
    title: {selector: 'h1.subj, h3.subj'}, author: {selector: '.detail_header .info .author'},
    authorFallback: {selector: '.detail_header .info .author_area'}, description: {selector: '#_asideDetail p.summary'},
    coverUrl: {selector: '.detail_header span.thmb img', attr: 'src', absolute: true},
    genre: {selector: '.detail_header .info .genre'}, day: {selector: '#_asideDetail p.day_info'},
    notice: {selector: '.detail_install_app'}
  }, canonical);
  if (!rows.length || !rows[0].title) throw new Error('咚漫：作品需要登录、年龄验证或详情格式已变更');
  var data = rows[0], author = (data.author || data.authorFallback || '').replace(/作家信息\s*$/, '').trim();
  var item = Object.assign({}, snapshot || {}, {remoteId: requestedId, url: canonical, title: data.title, author: author, coverUrl: (snapshot && snapshot.coverUrl) || data.coverUrl || '', description: (data.description || '') + (data.notice ? '\n\n[官方网页限制] ' + data.notice : ''), tags: data.genre ? [data.genre] : [], status: /完结|完結/.test(data.day || '') ? 'completed' : /更新/.test(data.day || '') ? 'ongoing' : 'unknown'});
  var queue = [], visited = {'1': true}, seen = {}, chapters = [];
  async function consume(pageBody, pageUrl) {
    var entries = await triomi.select(pageBody, '#_listUl li a[href*="/viewer?"]', {
      url: {selector: '.', attr: 'href', absolute: true}, title: {selector: '.subj span'}, fallback: {selector: '.subj'}
    }, pageUrl);
    if (!entries.length) throw new Error('咚漫：没有公开章节；可能仅限 APP、付费或需要登录');
    var before = chapters.length;
    for (var i = 0; i < entries.length; i++) {
      var row = entries[i], episode = param(row.url, 'episode_no');
      if (titleId(row.url) !== requestedId || !/^[1-9]\d*$/.test(episode)) throw new Error('咚漫：章节编号或归属异常');
      if (!seen[episode]) {
        seen[episode] = true;
        chapters.push({remoteId: requestedId + ':' + episode, title: row.title || row.fallback || ('第 ' + episode + ' 话'), url: row.url, number: Number(episode), volumeTitle: '公开网页章节'});
      }
    }
    if (chapters.length === before && pageUrl !== canonical) throw new Error('咚漫：官方重复返回章节页，无法取得完整公开目录');
    var links = await triomi.select(pageBody, '.paginate a[href*="page="]', {url: {selector: '.', attr: 'href', absolute: true}}, pageUrl);
    for (var j = 0; j < links.length; j++) {
      var link = links[j].url, p = param(link, 'page');
      if (!/^[1-9]\d*$/.test(p) || listUrl(link) !== canonical) throw new Error('咚漫：章节分页地址异常');
      if (!visited[p]) { visited[p] = true; queue.push(canonical + '&page=' + p); }
    }
  }
  await consume(body, canonical);
  while (queue.length) {
    var batch = queue.splice(0, 4);
    var pages = await Promise.all(batch.map(function (pageUrl) { return html(pageUrl, canonical); }));
    for (var k = 0; k < batch.length; k++) {
      if (listUrl(pages[k].url) !== canonical) throw new Error('咚漫：章节分页重新导向了其他作品');
      await consume(pages[k].body, batch[k]);
    }
  }
  chapters.sort(function (a,b) { return a.number - b.number; });
  return {item: item, chapters: chapters};
}
async function content(url, chapter) {
  official(url);
  var value = titleId(url), episode = param(url, 'episode_no');
  if (!/\/viewer\?/.test(url) || !/^[1-9]\d*$/.test(episode) || (chapter && chapter.remoteId && chapter.remoteId !== value + ':' + episode)) throw new Error('咚漫：章节地址或编号无效');
  var response = await html(url);
  if (titleId(response.url) !== value || param(response.url, 'episode_no') !== episode) throw new Error('咚漫：官方重新导向了其他章节，此话可能受限');
  var canonical = await triomi.value(response.body, 'meta[property="og:url"]', 'content', url);
  if (canonical && (!/^https?:\/\/www\.dongmanmanhua\.cn\//.test(canonical) || param(canonical, 'title_no') !== value || param(canonical, 'episode_no') !== episode)) throw new Error('咚漫：正文对应其他章节，此话可能受限');
  var rows = await triomi.select(response.body, '#_imageList > img', {image: {selector: '.', attr: 'data-url', absolute: true}}, url);
  if (!rows.length) throw new Error('咚漫：此话没有公开图片，可能仅限 APP、付费、登录或年龄验证，请到官方阅读');
  var images = rows.map(function (row) {
    // Preserve the official quality/query string; never rewrite to another host or endpoint.
    if (!/^https:\/\/cdn\.dongmanmanhua\.cn\/[^?#]+(?:[?][^#]*)?$/.test(row.image || '')) throw new Error('咚漫：正文图片地址异常或缺失，无法读取完整章节');
    return row.image;
  });
  return {images: images};
}
